// C documentation
//
//	// matches anything in the Zs class, plus LF, CR, TAB, FF.
func cmark_utf8proc_is_space(tls *libc.TLS, uc int32_t) (r int32) {
	return libc.BoolInt32(uc == int32(9) || uc == int32(10) || uc == int32(12) || uc == int32(13) || uc == int32(32) || uc == int32(160) || uc == int32(5760) || uc >= int32(8192) && uc <= int32(8202) || uc == int32(8239) || uc == int32(8287) || uc == int32(12288))
}

// C documentation
//
